import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"La dimostrazione","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fb/fbc.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fb/fbc.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fb/fbc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="la-dimostrazione" tabindex="-1">La dimostrazione <a class="header-anchor" href="#la-dimostrazione" aria-label="Permalink to “La dimostrazione”">​</a></h1><blockquote><p><strong>Nota importante:</strong> Spesso ho incontrato alunni che dicono: &quot;ma è evidente, perché devo dimostrarlo?&quot; Purtroppo quella macchina meravigliosa che è il nostro cervello talvolta ci porta a conclusioni sbagliate (se non ci credi prova a rispondere a queste domande), quindi serve un metodo per metterci al riparo da errori di cui non potremmo renderci conto: il metodo geometrico. Se io prendo un triangolo rettangolo ed un triangolo con l&#39;angolo che differisca per un millesimo di grado tu non sei in grado di distinguere quale dei due sia rettangolo, ma in uno sarà valido il teorema di Pitagora, nell&#39;altro no; da qui la necessità di dimostrare tutto, anche le cose che ci sembrano più ovvie (Inserire anche esempio dell&#39;area del triangolo).</p></blockquote><p>Ci mancano le regole &quot;operative&quot;, cioè quelle che ci permetteranno di passare da alcune conoscenze (ipotesi) ad altre conoscenze che derivano dalle prime (tesi). Il tutto sarà la dimostrazione.</p><p>La dimostrazione potrà effettuarsi mediante:</p><ul><li>[il teorema]{.text-red}: insieme di ragionamenti più o meno complicati</li><li>[il criterio]{.text-red}: scorciatoia per dimostrare qualcosa</li><li>[il lemma]{.text-red}: conseguenza immediata derivata da un teorema</li></ul><p>Il [teorema]{.text-red} potrà essere:</p><ul><li>diretto: con un ragionamento parto dall&#39;ipotesi ed arrivo alla tesi</li><li>per assurdo: si nega la tesi e se da questo si riesce a negare anche l&#39;ipotesi il teorema sarà vero</li></ul><blockquote><p>Se il ragionamento non ti convince troppo ti consoli il fatto che anche per parecchi matematici del passato il ragionamento non era valido perché richiama il principio del &quot;terzium non datur&quot;, cioè o una cosa è vera oppure è falsa e non ci sono alternative:</p><p>se da premesse vere si hanno conseguenze vere il ragionamento è valido equivale a se da conseguenze false si hanno premesse false il ragionamento è valido</p><p>Oggi tutti i matematici sono d&#39;accordo sulla bontà del metodo e potrai vedere nella logica (quando sarà scritta) il fondamento della dimostrazione per assurdo.</p></blockquote>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};